    public Object parseTrade(Object trade, Object... optionalArgs)
    {
        //
        // fetchTrades (public) v1
        //
        //      {
        //          "id":2278466664,
        //          "side":"SELL",
        //          "price":56810.7,
        //          "size":0.08798,
        //          "exec_date":"2021-11-19T11:46:39.323",
        //          "buy_child_order_acceptance_id":"JRF20211119-114209-236525",
        //          "sell_child_order_acceptance_id":"JRF20211119-114639-236919"
        //      }
        //
        // fetchMyTrades
        //
        //      {
        //          "id": 37233,
        //          "side": "BUY",
        //          "price": 33470,
        //          "size": 0.01,
        //          "exec_date": "2015-07-07T09:57:40.397",
        //          "child_order_id": "JOR20150707-060559-021935",
        //          "child_order_acceptance_id": "JRF20150707-060559-396699"
        //          "commission": 0,
        //      },
        //
        Object market = optionalArgs != null && optionalArgs.length > 0 ? optionalArgs[0] : null;
        String side = this.safeStringLower(trade, "side");
        if (!java.util.Objects.equals(side, null))
        {
            if (side.length() < 1)
            {
                side = null;
            }
        }
        Object order = null;
        if (!java.util.Objects.equals(side, null))
        {
            Object idInner = (side + "_child_order_acceptance_id");
            if (((Map<?, ?>)trade).containsKey(idInner))
            {
                order = Helpers.GetValue(trade, idInner);
            }
        }
        if (java.util.Objects.equals(order, null))
        {
            order = this.safeString(trade, "child_order_acceptance_id");
        }
        Long timestamp = this.parse8601(this.safeString(trade, "exec_date"));
        String priceString = this.safeString(trade, "price");
        String amountString = this.safeString(trade, "size");
        String id = this.safeString(trade, "id");
        market = this.safeMarket(null, market);
        final Object finalMarket = market;
        final Object finalOrder = order;
        final Object finalSide = side;
        return this.safeTrade(new HashMap<String, Object>() {{
            put( "id", id );
            put( "info", trade );
            put( "timestamp", timestamp );
            put( "datetime", Bitflyer.this.iso8601(timestamp) );
            put( "symbol", ((Map<String, Object>)finalMarket).get("symbol") );
            put( "order", finalOrder );
            put( "type", null );
            put( "side", finalSide );
            put( "takerOrMaker", null );
            put( "price", priceString );
            put( "amount", amountString );
            put( "cost", null );
            put( "fee", null );
        }}, market);
    }

