    public Object parseTransaction(Object transaction, Object... optionalArgs)
    {
        //
        // fetchDeposits
        //
        //     {
        //         "id": 100,
        //         "order_id": "CDP20151227-024141-055555",
        //         "currency_code": "BTC",
        //         "amount": 0.00002,
        //         "address": "1WriteySQufKZ2pVuM1oMhPrTtTVFq35j",
        //         "tx_hash": "9f92ee65a176bb9545f7becb8706c50d07d4cee5ffca34d8be3ef11d411405ae",
        //         "status": "COMPLETED",
        //         "event_date": "2015-11-27T08:59:20.301"
        //     }
        //
        // fetchWithdrawals
        //
        //     {
        //         "id": 500,
        //         "order_id": "CWD20151224-014040-077777",
        //         "currency_code": "BTC",
        //         "amount": 0.1234,
        //         "address": "1A1zP1eP5QGefi2DMPTfTL5SLmv7DivfNa",
        //         "tx_hash": "724c07dfd4044abcb390b0412c3e707dd5c4f373f0a52b3bd295ce32b478c60a",
        //         "fee": 0.0005,
        //         "additional_fee": 0.0001,
        //         "status": "COMPLETED",
        //         "event_date": "2015-12-24T01:40:40.397"
        //     }
        //
        // withdraw
        //
        //     {
        //         "message_id": "69476620-5056-4003-bcbe-42658a2b041b"
        //     }
        //
        Object currency = optionalArgs != null && optionalArgs.length > 0 ? optionalArgs[0] : null;
        String id = this.safeString2(transaction, "id", "message_id");
        String address = this.safeString(transaction, "address");
        String currencyId = this.safeString(transaction, "currency_code");
        String code = this.safeCurrencyCode(currencyId, currency);
        Long timestamp = this.parse8601(this.safeString(transaction, "event_date"));
        Double amount = this.safeNumber(transaction, "amount");
        String txId = this.safeString(transaction, "tx_hash");
        String rawStatus = this.safeString(transaction, "status");
        String type = null;
        String status = null;
        Object fee = null;
        if (((Map<?, ?>)transaction).containsKey("fee"))
        {
            type = "withdrawal";
            status = this.parseWithdrawalStatus(rawStatus);
            String feeCost = this.safeString(transaction, "fee");
            String additionalFee = this.safeString(transaction, "additional_fee");
            fee = new HashMap<String, Object>() {{
                put( "currency", code );
                put( "cost", Bitflyer.this.parseNumber(Precise.stringAdd(feeCost, additionalFee)) );
            }};
        } else
        {
            type = "deposit";
            status = this.parseDepositStatus(rawStatus);
        }
        final Object finalType = type;
        final Object finalStatus = status;
        final Object finalFee = fee;
        return new HashMap<String, Object>() {{
            put( "info", transaction );
            put( "id", id );
            put( "txid", txId );
            put( "timestamp", timestamp );
            put( "datetime", Bitflyer.this.iso8601(timestamp) );
            put( "network", null );
            put( "address", address );
            put( "addressTo", address );
            put( "addressFrom", null );
            put( "tag", null );
            put( "tagTo", null );
            put( "tagFrom", null );
            put( "type", finalType );
            put( "amount", amount );
            put( "currency", code );
            put( "status", finalStatus );
            put( "updated", null );
            put( "comment", null );
            put( "internal", null );
            put( "fee", finalFee );
        }};
    }

